   G("Tempest Bell", ["Overabundance I", "Close Combat I"], L("Sino que os golpes explodem", "Bell your hits detonate"), L("Uncut nível 3. Você ganha Combo batendo com outras skills; no Combo máximo, use para largar um sino enorme no chão: ele causa dano e pode ser atingido, criando uma onda de choque.", "Level 3 Uncut. You build Combo by hitting with other skills; at max Combo, use it to drop a huge bell: it damages on impact and can be hit, creating a shockwave."), "free", since=23),
   G("Herald of Thunder", ["Longshot I", "Electrocute"], L("Raios ao matar", "Lightning on kill"), L("Uncut Spirit Gem nível 4, 30 Spirit (King in the Mists). Matar um inimigo Chocado com um ataque solta raios que atingem tudo em volta.", "Level 4 Uncut Spirit Gem, 30 Spirit (King in the Mists). Killing a Shocked enemy with an attack releases lightning bolts that hit everything around."), "core", 1, SP30, since=23),
   G("Charged Staff", ["Shock", "Innervate"], L("Buff de Power Charges", "Power Charge buff"), L("Uncut nível 9, quarterstaff. Consome todos os Power Charges para carregar o cajado com raio: dano de raio e uma onda de choque nos seus ataques.", "Level 9 Uncut, quarterstaff. Consumes all Power Charges to charge your staff with lightning: lightning damage and a shockwave on your attacks."), "free", since=23),
