  rotation=[L("Storm Wave no pack e no boss", "Storm Wave on packs and bosses"), L("Tempest Bell + Tempest Flurry no boss", "Tempest Bell + Tempest Flurry on the boss"), L("Herald of Thunder e Herald of Ash sempre ligados", "Herald of Thunder and Herald of Ash always on")],
