TRICKS = [
 {"cat": L("Skills", "Skills"), "lvl": L("Fácil", "Easy"), "title": L("3× Whirling Slash e um Twister", "3× Whirling Slash and one Twister"), "body": L("No leveling de spear (1–22) o autor manda usar a Whirling Slash 3 vezes antes do Twister: assim um único Twister junta mais vento e dá muito mais dano. Repita o combo. Não gaste Orbs abrindo sockets nessas duas gems.", "In spear leveling (1–22) the author says to use Whirling Slash 3 times before Twister: that way a single Twister gathers more wind and deals much more damage. Repeat the combo. Don't spend Orbs adding sockets to those two gems.")},
 {"cat": L("Setup", "Setup"), "lvl": L("Fácil", "Easy"), "title": L("Hollow Palm Technique ANTES de largar a arma", "Hollow Palm Technique BEFORE dropping the weapon"), "body": L("As skills de cajado só funcionam sem arma com o nó Hollow Palm Technique alocado (entre o 23 e o 25). Só depois tire a spear do Set 1. A velocidade de ataque passa a vir da Evasion do equipamento (1% a cada 75) e o crítico do Energy Shield (+0,1% a cada 10).", "Quarterstaff skills only work without a weapon with the Hollow Palm Technique node allocated (between 23 and 25). Only then take the spear out of Set 1. Attack speed now comes from the Evasion on your gear (1% per 75) and crit from Energy Shield (+0.1% per 10).")},
 {"cat": L("Cargas", "Charges"), "lvl": L("Médio", "Medium"), "title": L("A ORDEM dos suportes do Hollow Focus", "The ORDER of Hollow Focus's supports"), "body": L("Para gerar Power Charges coloque no Hollow Focus Living Lightning II, depois Culmination II e depois Ailith's Chimes, NESSA ORDEM: assim se forma o Combo (mesmo sem você ver) e, quando ele é gasto, vêm as cargas para o Charged Staff e o Falling Thunder. Se não gerar cargas, ponha dano de raio flat no anel ou na arma para o Living Lightning II disparar mais vezes.", "To generate Power Charges put Living Lightning II, then Culmination II, then Ailith's Chimes on Hollow Focus, IN THAT ORDER: that's how the Combo forms (even if you can't see it) and, when it's spent, you get charges for Charged Staff and Falling Thunder. If you're not generating charges, put flat lightning damage on a ring or the weapon so Living Lightning II triggers more often.")},
 {"cat": L("Skills", "Skills"), "lvl": L("Médio", "Medium"), "title": L("Mantenha o buff do Staggering Palm", "Keep Staggering Palm's buff up"), "body": L("O buff que faz seus ataques dispararem projéteis vem de dar Heavy Stun com o Staggering Palm nos sinos do Hollow Focus algumas vezes a cada 30 s: olhe o canto esquerdo da tela para ver se está ativo. Na luta você pode segurar o botão do Staggering Palm para repetir e reativar nos sinos que aparecem.", "The buff that makes your attacks fire projectiles comes from Heavy Stunning Hollow Focus's bells with Staggering Palm a few times every 30 s: check the left corner of the screen to see if it's active. In a fight you can hold the Staggering Palm button to repeat it and re-trigger it on newly spawned bells.")},
 {"cat": L("Boss", "Boss"), "lvl": L("Médio", "Medium"), "title": L("Falling Thunder só com as 5 cargas", "Falling Thunder only with 5 charges"), "body": L("Use o Falling Thunder contra Rare ou boss que não está derretendo, mas SÓ com as 5 Power Charges. Bata no alvo algumas vezes antes para Dazar e Cegar (o Blindside precisa disso) e mantenha 83%+ de crítico na skill com o Pinpoint Critical (assim vira 100% com os passivos de Daze). Antes da luta, use o Killing Palm nos sinos do Hollow Focus para começar com as cargas cheias.", "Use Falling Thunder against a Rare or boss that isn't melting, but ONLY with all 5 Power Charges. Hit the target a few times first to Daze and Blind it (Blindside needs that) and keep 83%+ crit on the skill with Pinpoint Critical (so it becomes 100% with the Daze passives). Before the fight, use Killing Palm on Hollow Focus's bells to start with full charges.")},
 {"cat": L("Mana", "Mana"), "lvl": L("Fácil", "Easy"), "title": L("Como resolver a mana", "How to fix mana"), "body": L("Oisín's Oath dentro do Hollow Focus mais Leech Physical Damage as Mana em UM dos anéis devem bastar. Manter o Tempest Flurry no nível 5 e usar o Efficiency II também ajuda muito.", "Oisín's Oath inside Hollow Focus plus Leech Physical Damage as Mana on ONE of your rings should be enough. Keeping Tempest Flurry at level 5 and using Efficiency II also helps a lot.")},
 {"cat": L("Setup", "Setup"), "lvl": L("Fácil", "Easy"), "title": L("Weapon Sets", "Weapon Sets"), "body": L("Todas as skills ficam no Weapon Set 1 (é onde está a velocidade); só o Falling Thunder fica no Weapon Set 2, com o Sinister Quarterstaff, para bater mais forte em boss e Rare. Os nós de Weapon Set da árvore seguem essa divisão.", "All skills go in Weapon Set 1 (that's where the speed is); only Falling Thunder goes in Weapon Set 2, with the Sinister Quarterstaff, to hit bosses and Rares harder. The tree's Weapon Set nodes follow that split.")},
 {"cat": L("Defesa", "Defence"), "lvl": L("Fácil", "Easy"), "title": L("Como não tomar Stun", "How not to get Stunned"), "body": L("Pegue UM notável de Stun Threshold no caminho até Abasement, ou vá mais longe se ainda estiver tomando stun. Nas joias procure 'Gain % of Energy Shield as Stun Threshold'. A recompensa do Venom Draught (Venom Crypts, Ato 3) também dá Stun Threshold.", "Take ONE Stun Threshold notable on the way to Abasement, or go further if you're still getting stunned. On jewels look for 'Gain % of Energy Shield as Stun Threshold'. The Venom Draught reward (Venom Crypts, Act 3) also gives Stun Threshold.")},
 {"cat": L("Gems", "Gems"), "lvl": L("Fácil", "Easy"), "title": L("Herald of Ash no 4, Tempest Flurry no 5", "Herald of Ash at 4, Tempest Flurry at 5"), "body": L("Nas variantes de endgame o autor manda manter o Herald of Ash no nível 4 e o Tempest Flurry no nível 5 (mais barato de mana) e subir o resto das gems o máximo que der.", "In the endgame variants the author says keep Herald of Ash at level 4 and Tempest Flurry at level 5 (cheaper on mana) and level the rest of the gems as high as you can.")},
 {"cat": L("Itens", "Items"), "lvl": L("Médio", "Medium"), "title": L("Luvas do Way of the Stonefist", "Way of the Stonefist gloves"), "body": L("As luvas viram Fists of Stone: procure DOIS danos adicionados de tier alto (qualquer combinação de fogo, raio, frio ou físico), Evasion flat T1 (ou híbrida) para a velocidade, velocidade de cast com a vida cheia (vira velocidade de ataque, e você está sempre com a vida cheia) e Dexterity (chance de projétil extra).", "The gloves become Fists of Stone: look for TWO high-tier added damage mods (any mix of fire, lightning, cold or physical), T1 flat Evasion (or hybrid) for speed, cast speed on Full Life (it becomes attack speed, and you're always on Full Life) and Dexterity (a chance for an extra projectile).")},
 {"cat": L("Defesa", "Defence"), "lvl": L("Difícil", "Hard"), "title": L("Quando fazer a troca para Chaos Inoculation", "When to switch to Chaos Inoculation"), "body": L("O Chaos Inoculation deixa a vida máxima em 1: toda a defesa vira Energy Shield. O autor só faz com corpo de 1400–1500 de Evasion e uns 500 de ES e capacete com uns 500 de ES (o endgame dele tem 6.000+ de ES, 60% de Evasion e Deflection). Antes disso fique na árvore de vida. A troca é grande: uns 26 pontos saem e 43 entram.", "Chaos Inoculation leaves maximum life at 1: all your defence becomes Energy Shield. The author only does it with a 1400–1500 Evasion, ~500 ES body and a ~500 ES helmet (his endgame has 6,000+ ES, 60% Evasion and Deflection). Before that stay on the life tree. The switch is big: about 26 points out and 43 in.")},
 {"cat": L("Itens", "Items"), "lvl": L("Fácil", "Easy"), "title": L("Joia com 'Gain 1 Rage on melee hit'", "A jewel with 'Gain 1 Rage on melee hit'"), "body": L("O autor manda pegar essa joia o quanto antes na campanha: a Rage alimenta o Rage III (velocidade) do Tempest Flurry e do Storm Wave.", "The author says to get that jewel as early as you can in the campaign: Rage feeds Rage III (speed) on Tempest Flurry and Storm Wave.")},
]
TROUBLESHOOT = [
 (L("As skills de cajado não funcionam sem arma", "Quarterstaff skills don't work without a weapon"), L("Falta o Hollow Palm Technique na árvore (nível 23–25). Sem ele você precisa de uma arma equipada. Aloque o nó antes de tirar a spear.", "Hollow Palm Technique is missing from your tree (level 23–25). Without it you need a weapon equipped. Allocate the node before taking the spear off.")),
 (L("O Tempest Flurry parece lento", "Tempest Flurry feels slow"), L("A velocidade vem da Evasion do equipamento (1% a cada 75). Confira o corpo (o mais importante), as botas e o capacete; o Rage III só ajuda com Rage abaixo do máximo, então pegue a joia 'Gain 1 Rage on melee hit'. As luvas com velocidade de cast na vida cheia também viram velocidade de ataque.", "Speed comes from the Evasion on your gear (1% per 75). Check the body armour (the most important), boots and helmet; Rage III only helps with Rage below maximum, so get the 'Gain 1 Rage on melee hit' jewel. Gloves with cast speed on Full Life also become attack speed.")),
 (L("Não gero Power Charges", "I'm not generating Power Charges"), L("Confira a ordem dos suportes do Hollow Focus: Living Lightning II → Culmination II → Ailith's Chimes. Se a ordem está certa, falta dano de raio para disparar o Living Lightning II: ponha dano de raio flat no anel ou na arma. No boss use o Killing Palm nos sinos antes da luta.", "Check the order of Hollow Focus's supports: Living Lightning II → Culmination II → Ailith's Chimes. If the order is right, you lack lightning damage to trigger Living Lightning II: put flat lightning damage on a ring or the weapon. On bosses use Killing Palm on the bells before the fight.")),
 (L("Fico sem mana", "I run out of mana"), L("Oisín's Oath no Hollow Focus e Leech Physical Damage as Mana em um anel; Efficiency II no Tempest Flurry e o Tempest Flurry no nível 5.", "Oisín's Oath on Hollow Focus and Leech Physical Damage as Mana on a ring; Efficiency II on Tempest Flurry and Tempest Flurry at level 5.")),
 (L("Levo Stun demais", "I get Stunned too much"), L("Um notável de Stun Threshold no caminho de Abasement, joias com 'Gain % of Energy Shield as Stun Threshold' e a recompensa do Venom Draught.", "One Stun Threshold notable on the way to Abasement, jewels with 'Gain % of Energy Shield as Stun Threshold' and the Venom Draught reward.")),
 (L("Morro de um golpe depois do Chaos Inoculation", "I die to one hit after Chaos Inoculation"), L("Com CI a vida é 1: só a barra de ES te protege. Volte à árvore de vida se o ES está abaixo de ~6.000 no endgame ou se o corpo/capacete ainda não têm ~500 de ES; feche resistências, pegue Deflection e 'faster start of ES Recharge' e use um Life Flask de recuperação instantânea com o Shavronne's Satchel.", "With CI your life is 1: only the ES bar protects you. Go back to the life tree if ES is below ~6,000 in endgame or the body/helmet don't have ~500 ES yet; cap resistances, get Deflection and 'faster start of ES Recharge' and use an instant-recovery Life Flask with Shavronne's Satchel.")),
 (L("Não fecho o Spirit", "Spirit doesn't add up"), L("Herald of Thunder 30 + Herald of Ash 30 + Lingering Illusion 30 = 90 dos 100 das quests (King in the Mists, Ignagduk, Lythara). No Waystones sai o Herald of Thunder e o Lingering Illusion e entram Wind Dancer e Ghost Dance. O Trinity (100) do endgame precisa do Spirit do equipamento: confira no jogo.", "Herald of Thunder 30 + Herald of Ash 30 + Lingering Illusion 30 = 90 of the quests' 100 (King in the Mists, Ignagduk, Lythara). In Waystones Herald of Thunder and Lingering Illusion leave and Wind Dancer and Ghost Dance come in. Endgame's Trinity (100) needs Spirit from gear: check in game.")),
 (L("Estou fraco para o meu nível", "I'm weak for my level"), L("Confira: corpo com muita Evasion, +níveis de Melee no amuleto (+3) e nas luvas (+2), dano adicionado nos anéis e nas luvas, os nós de dano da árvore (Concussive Attack, Blinding Strike, Killer Instinct) e a joia de Rage. Se o combo Tempest Bell + Tempest Flurry incomoda, use só o Storm Wave.", "Check: a body armour with lots of Evasion, + Melee levels on the amulet (+3) and gloves (+2), added damage on rings and gloves, the tree's damage nodes (Concussive Attack, Blinding Strike, Killer Instinct) and the Rage jewel. If the Tempest Bell + Tempest Flurry combo bothers you, use Storm Wave alone.")),
]
